create policy "profile_covers_authenticated_insert_own"
on storage.objects
for insert
to authenticated
with check (((bucket_id = 'profile-covers'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));

drop policy if exists "profile_covers_authenticated_update_own" on storage.objects;
create policy "profile_covers_authenticated_update_own"
on storage.objects
for update
to authenticated
using (((bucket_id = 'profile-covers'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)))
with check (((bucket_id = 'profile-covers'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));

commit;
